// Utility module for handling common path operations
// Exported helpers can be imported elsewhere in the project

import path from "path";

/**
 * Join path segments using POSIX style separators.
 * Works in both Node and Termux environments.
 */
export function join(...segments) {
  return segments
    .filter(Boolean)
    .map((s) => s.replace(/^\/+|\/+$/g, ""))
    .join("/");
}

/**
 * Resolve a relative path against a base directory.
 * If the relative path is actually absolute, it is returned unchanged.
 */
export function resolve(base, relative) {
  if (!relative) return base;
  if (relative.startsWith("/")) return relative;
  return join(base, relative);
}

/**
 * Return the file extension (including the dot) of a filename.
 * Example: extname('data.json') => '.json'
 */
export function extname(filename) {
  const idx = filename.lastIndexOf('.');
  return idx !== -1 ? filename.slice(idx) : '';
}

/**
 * Strip the extension from a filename.
 * Example: basename('data.json') => 'data'
 */
export function basename(filename) {
  const idx = filename.lastIndexOf('.');
  return idx !== -1 ? filename.slice(0, idx) : filename;
}

/**
 * Ensure a path ends with a trailing slash.
 */
export function ensureTrailingSlash(p) {
  return p.endsWith('/') ? p : p + '/';
}

/**
 * Remove a trailing slash from a path (except when the path is just '/').
 */
export function removeTrailingSlash(p) {
  return p !== '/' && p.endsWith('/') ? p.slice(0, -1) : p;
}
